Definition dbp_frame (m : mem) (a : Z) (j8 j40 : list byte) (s2v s1v s0v rav : word) : Prop :=
  rw_cells rsegs m a [CB 8 j8; CB 40 j40; C8 s2v; C8 s1v; C8 s0v; C8 rav].

Definition dbp_seg1_post (sp : word) (gp tp : word) (s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 ra : word) (F : bvmap 5 word) (fc : bv 32)
    (R b n E lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' j8 j40 pad7 j39,
    ms' = MS (mkR (wz P_DBP_RET) (wz (bv_unsigned sp - 80)) gp tp t0 t1 t2 (wz E) (wz R) (wz (bv_unsigned sp - 72)) (wz b) (wz n)
                  a3 a4 a5 a6 a7 (wz 7) s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 P_MB_PREPARE) fc None m' (seg_rom rsegs)
    /\ munch [(lo, bv_unsigned sp); (R, R + 48)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp - 80)
    /\ dbp_frame m' (bv_unsigned sp - 80) j8 j40 s2 s1 s0 ra
    /\ rw_cells rsegs m' R [C1 (b8 0); CB 7 pad7; CB 40 j39].

Definition dbp_seg1_stmt : Prop := forall (R b n E lo : Z) (rj : list byte)
    (ra sp : word) gp tp (t0 t1 t2 s0 s1 a3 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) fc (m : mem),
  rw_cells rsegs m R [CB 48 rj] -> bv_unsigned sp <= R -> R + 48 <= 2^64 ->
  stk rsegs m lo (bv_unsigned sp) -> lo + 80 <= bv_unsigned sp -> hceil <= lo ->
  mem_inv rsegs m ->
  evt rsegs (dbp_seg1_post sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 ra F fc R b n E lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz R) (wz b) (wz n) (wz E) (wz 7) a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_MB_DYN_PREPARE) fc None m (seg_rom rsegs)).
