Definition put_frame (m : mem) (a : Z) (j8 j48 j16a j16b : list byte) (s3v s2v s1v s0v rav : word) : Prop :=
  rw_cells rsegs m a [CB 8 j8; CB 48 j48; CB 16 j16a; CB 16 j16b; C8 s3v; C8 s2v; C8 s1v; C8 s0v; C8 rav].

Definition put_seg1_post (sp : word) (gp tp : word) (s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 ra : word) (F : bvmap 5 word) (fc : bv 32)
